package com.motionstudio.part2
object MotionBlur { fun apply(src:FrameBuffer,dx:Float,dy:Float,shutterAngle:Float=180f,shutterPhase:Float=0f,samples:Int=8):FrameBuffer{require(samples>0&&samples<=128);val scale=shutterAngle.coerceIn(0f,360f)/360f;val o=FrameBuffer(src.width,src.height);for(y in 0 until src.height)for(x in 0 until src.width){var r=0f;var g=0f;var b=0f;var a=0f;for(i in 0 until samples){val u=if(samples==1).5f else i.toFloat()/(samples-1);val t=(u-.5f+shutterPhase)*scale;val c=src.bilinear(x+dx*t,y+dy*t);r+=c.r;g+=c.g;b+=c.b;a+=c.a};o.set(x,y,Rgba(r/samples,g/samples,b/samples,a/samples))};return o}}
